+func readKVContentForMerge(path, root string) (string, error) {
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return "", err
+	}
+	text := strings.TrimPrefix(string(data), "\ufeff")
+	if inner, ok := extractRootInner(text, root); ok {
+		text = inner
+	}
+	return strings.TrimRight(text, " \t\r\n"), nil
+}
+
+func extractRootInner(text, root string) (string, bool) {
+	i := 0
+	for i < len(text) {
+		i = skipWSAndComments(text, i)
+		if i >= len(text) {
+			break
+		}
+		if text[i] != '"' {
+			i++
+			continue
+		}
+		val, next, ok := readQuotedString(text, i)
+		if !ok {
+			return "", false
+		}
+		i = next
+		if val != root {
+			continue
+		}
+		i = skipWSAndComments(text, i)
+		if i >= len(text) || text[i] != '{' {
+			continue
+		}
+		end, ok := findMatchingBrace(text, i)
+		if !ok {
+			return "", false
+		}
+		return text[i+1 : end], true
+	}
+	return "", false
+}
+
+func skipWSAndComments(s string, i int) int {
+	for i < len(s) {
+		ch := s[i]
+		if ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n' {
+			i++
+			continue
+		}
+		if ch == '/' && i+1 < len(s) {
+			next := s[i+1]
+			if next == '/' {
+				i += 2
+				for i < len(s) && s[i] != '\n' {
+					i++
+				}
+				continue
+			}
+			if next == '*' {
+				i += 2
+				for i+1 < len(s) {
+					if s[i] == '*' && s[i+1] == '/' {
+						i += 2
+						break
+					}
+					i++
+				}
+				continue
+			}
+		}
+		break
+	}
+	return i
+}
+
+func readQuotedString(s string, i int) (string, int, bool) {
+	if i >= len(s) || s[i] != '"' {
+		return "", i, false
+	}
+	i++
+	var b strings.Builder
+	escape := false
+	for i < len(s) {
+		ch := s[i]
+		if escape {
+			b.WriteByte(ch)
+			escape = false
+			i++
+			continue
+		}
+		if ch == '\\' {
