+		}
+		b.WriteByte(ch)
+		i++
+	}
+	return "", i, false
+}
+
+func findMatchingBrace(s string, start int) (int, bool) {
+	if start < 0 || start >= len(s) || s[start] != '{' {
+		return -1, false
+	}
+	depth := 0
+	inStr := false
+	escape := false
+	inLineComment := false
+	inBlockComment := false
+
+	for i := start; i < len(s); i++ {
+		ch := s[i]
+		if inLineComment {
+			if ch == '\n' {
+				inLineComment = false
+			}
+			continue
+		}
+		if inBlockComment {
