+		if ch == '/' && i+1 < len(s) {
+			next := s[i+1]
+			if next == '/' {
+				inLineComment = true
+				i++
+				continue
+			}
+			if next == '*' {
+				inBlockComment = true
+				i++
+				continue
+			}
+		}
+		if ch == '{' {
+			depth++
+			continue
+		}
+		if ch == '}' {
